export const grammarSetsA=[
{id:'gram-1',title:'Grammatik 1: På arbejde og derhjemme',level:'B2',minutes:15,items:[
{id:'g1-01',cat:'v2',type:'order',
 tokens:['kan','chefen','Desværre','ikke','komme','i','dag.'],
 answers:['Desværre kan chefen ikke komme i dag.','Chefen kan desværre ikke komme i dag.','I dag kan chefen desværre ikke komme.'],
 why:'В главном предложении глагол всегда на втором месте: если впереди наречие (Desværre), подлежащее идёт после глагола. Если начать с подлежащего, наречия desværre и ikke стоят после глагола.'},
{id:'g1-02',cat:'tenses',type:'gap',
 stem:'Jeg ___ aldrig været i Aalborg, før jeg flyttede dertil.',
 options:['har','havde','var','blev'],answer:1,
 why:'Действие «никогда не был» предшествует другому прошедшему действию (flyttede), поэтому нужен pluskvamperfektum: havde + причастие. Har — настоящее время, var/blev с været не образуют прошедшее.'},
{id:'g1-03',cat:'agree',type:'fix',
 sentence:'Vi bor i en stort hus tæt på stationen.',errorIndex:3,fixes:['et'],
 why:'Hus — слово среднего рода (et hus), поэтому и артикль, и прилагательное в форме среднего рода: et stort hus. Ошибка в неопределённом артикле en.'},
{id:'g1-04',cat:'passive',type:'transform',
 prompt:'Man reparerer cyklerne i værkstedet.',
 instruction:'Перепиши в пассиве без указания деятеля. Начни с: Cyklerne …',
 answers:['Cyklerne repareres i værkstedet.','Cyklerne bliver repareret i værkstedet.'],
 why:'Пассив образуется двумя способами: s-пассив (repareres) или blive + причастие (bliver repareret). Объект действия становится подлежащим, а man исчезает.'},
{id:'g1-05',cat:'relative',type:'gap',
 stem:'Det er den kollega, ___ cykel blev stjålet.',
 options:['som','der','hvem','hvis'],answer:3,
 why:'Здесь нужно относительное слово со значением «чей»: hvis cykel. Som и der не выражают принадлежность, hvem не употребляется как относительное слово при существительном.'},
{id:'g1-06',cat:'bisaet',type:'order',
 tokens:['hun','Min','ikke','fortæller,','kollega','har','at','fået','svar.','desværre'],
 answers:['Min kollega fortæller, at hun desværre ikke har fået svar.'],
 why:'В придаточном предложении подлежащее стоит перед отрицанием и наречием, а они — перед глаголом: at hun desværre ikke har fået. В главном предложении глагол стоял бы перед ними: Hun har desværre ikke fået svar.'},
{id:'g1-07',cat:'reflex',type:'fix',
 sentence:'Alle børnene i klassen glæder dem til sommerferien.',errorIndex:5,fixes:['sig'],
 why:'Когда действие направлено на само подлежащее (3-е лицо), используется возвратное sig: glæde sig til noget. Dem означало бы «других людей».'},
{id:'g1-08',cat:'prep',type:'gap',
 stem:'Pernille er meget interesseret ___ det nye projekt.',
 options:['i','på','af','med'],answer:0,
 why:'Устойчивое сочетание: være interesseret i noget. Другие предлоги с этим прилагательным не употребляются.'},
{id:'g1-09',cat:'modal',type:'transform',
 prompt:'Det er nødvendigt, at vi sender svaret i dag.',
 instruction:'Замени конструкцию «det er nødvendigt, at» модальным глаголом (skal или må). Начни с: Vi …',
 answers:['Vi skal sende svaret i dag.','Vi må sende svaret i dag.'],
 why:'После модальных глаголов (skal, må) инфинитив стоит без at: Vi skal sende. Оба глагола передают необходимость.'},
{id:'g1-10',cat:'connect',type:'cloze',
 segments:['Mette havde glædet sig til sommerferien, ',{gap:1,options:['selvom','hvis','fordi','medmindre'],answer:2},' hun skulle til Bornholm med sin familie. Den første uge regnede det hele tiden. ',{gap:2,options:['Derfor','Fordi','Selvom','Medmindre'],answer:0},' blev de i sommerhuset og spillede kort. ',{gap:3,options:['Derfor','Selvom','Medmindre','Mens'],answer:3},' børnene lavede puslespil, læste Mette en bog. Til sidst blev vejret bedre, men de måtte tage hjem, ',{gap:4,options:['selvom','fordi','mens','medmindre'],answer:1},' hendes mand skulle på arbejde igen. ',{gap:5,options:['Derfor','Fordi','Alligevel','Medmindre'],answer:2},' var hun glad for turen.'],
 why:'Fordi даёт причину, derfor и alligevel — связки главного предложения (после них порядок V2: Derfor blev de), mens означает «пока», selvom — «хотя», medmindre — «если только не». Нужно подобрать связку по смыслу.'}
]}
,{id:'gram-2',title:'Grammatik 2: Rejser, vaner og planer',level:'B2',minutes:15,items:[
{id:'g2-01',cat:'compare',type:'gap',
 stem:'Hvis du vil spare penge, skal du købe ___ grøntsager og mindre kød.',
 options:['mere','mest','flere','meget'],answer:2,
 why:'Перед исчисляемым существительным во множественном числе (grøntsager) ставится flere, перед неисчисляемым — mere (mere kød). Mest — превосходная степень, а meget не употребляется перед множественным числом.'},
{id:'g2-02',cat:'cond',type:'transform',
 prompt:'Jeg har ikke råd til en bil, så jeg cykler på arbejde.',
 instruction:'Перепиши как нереальное условие в настоящем. Начни с: Hvis jeg … или с: Havde jeg …',
 answers:['Hvis jeg havde råd til en bil, ville jeg ikke cykle på arbejde.','Havde jeg råd til en bil, ville jeg ikke cykle på arbejde.'],
 why:'Нереальное условие в настоящем: в условной части præteritum (havde), в главной — ville + инфинитив без at. Условие можно выразить и инверсией без hvis: Havde jeg råd …, ville jeg …'},
{id:'g2-03',cat:'v2',type:'transform',
 prompt:'Min søster skal holde et foredrag i Odense næste uge.',
 instruction:'Перепиши, поставив в начало одно из обстоятельств (места или времени).',
 answers:['I Odense skal min søster holde et foredrag næste uge.','Næste uge skal min søster holde et foredrag i Odense.'],
 why:'Если на первое место выходит обстоятельство, подлежащее и глагол меняются местами (инверсия): глагол остаётся на втором месте. Skal min søster …, а не min søster skal.'},
{id:'g2-04',cat:'bisaet',type:'order',
 tokens:['er','Selvom','ofte','han','arbejder','sent,','han','altid','frisk','om','morgenen.'],
 answers:['Selvom han ofte arbejder sent, er han altid frisk om morgenen.','Selvom han altid arbejder sent, er han ofte frisk om morgenen.'],
 why:'В придаточном (selvom) наречие ofte стоит перед глаголом: han ofte arbejder. Главное предложение после придаточного в начале начинается с глагола (инверсия): …, er han altid frisk.'},
{id:'g2-05',cat:'passive',type:'fix',
 sentence:'Huset blev bygges i 1990 af en lokal murer.',errorIndex:2,fixes:['bygget'],
 why:'Пассив с blive требует причастия: blev bygget. Форма на -s (bygges) не сочетается с blev: нельзя смешивать два способа образования пассива.'},
{id:'g2-06',cat:'tenses',type:'cloze',
 segments:['Indtil for et år siden ',{gap:1,options:['har','havde','var','blev'],answer:1},' Jens aldrig arbejdet i en café, men så ',{gap:2,options:['åbnede','åbner','har åbnet','havde åbnet'],answer:0},' han sin egen i Odense. I begyndelsen kom der få gæster, men i dag ',{gap:3,options:['havde','er','blev','har'],answer:3},' han allerede fået mange faste kunder. Da journalisten kom på besøg i går, ',{gap:4,options:['var','havde','blev','har'],answer:1},' han lige bagt en ny kage. I morgen ',{gap:5,options:['skrev','skrevet','skriver','havde skrevet'],answer:2},' avisen om caféen.'],
 why:'Pluskvamperfektum (havde arbejdet, havde bagt) — действие до другого момента в прошлом; præteritum (åbnede) — завершённое действие в повествовании; perfektum (har fået) — результат, важный сейчас; с i morgen будущее выражается настоящим временем (skriver).'},
{id:'g2-07',cat:'relative',type:'gap',
 stem:'Hun spurgte, ___ af de to huse vi ville købe.',
 options:['hvilket','hvilken','hvilke','hvad'],answer:0,
 why:'Hvilken/hvilket/hvilke согласуется с существительным в роде и числе. Hus — средний род, речь об одном доме, поэтому hvilket. Hvilken — общий род, hvilke — множественное число, hvad не сочетается с af de to huse.'},
{id:'g2-08',cat:'connect',type:'order',
 tokens:['kom','vi','Derfor','for','sent','til','mødet.'],
 answers:['Derfor kom vi for sent til mødet.','Vi kom derfor for sent til mødet.'],
 why:'Derfor — наречие-связка. В начале предложения за ним следует инверсия (Derfor kom vi), а внутри предложения оно стоит после подлежащего и глагола (Vi kom derfor …).'},
{id:'g2-09',cat:'prep',type:'fix',
 sentence:'Min bror har arbejdet i Norge siden tre år.',errorIndex:6,fixes:['i'],
 why:'Siden указывает на начальную точку (siden 2019, siden i går). Для срока «три года» нужен предлог i: i tre år.'},
{id:'g2-10',cat:'agree',type:'gap',
 stem:'Der står mange ___ på bordet.',
 options:['glasset','glasene','glassene','glas'],answer:3,
 why:'После mange нужна неопределённая форма множественного числа. У слова glas (средний род) она совпадает с единственным числом: glas. Glasset — единственное определённое, glassene — множественное определённое, а формы glasene не существует.'}
]}
,{id:'gram-3',title:'Grammatik 3: Fritid og fællesskab',level:'B2',minutes:15,items:[
{id:'g3-01',cat:'cond',type:'order',
 tokens:['vi','Hvis','havde','haft','flere','penge,','ville','vi','være','rejst','til','Italien.'],
 answers:['Hvis vi havde haft flere penge, ville vi være rejst til Italien.'],
 why:'Нереальное условие в прошлом: в условной части hvis + havde + причастие (havde haft), в главной — ville + være/have + причастие (ville være rejst). После придаточного в начале главное предложение начинается с глагола: …, ville vi.'},
{id:'g3-02',cat:'reflex',type:'gap',
 stem:'Børnene tog ___ jakker på og løb ud i regnen.',
 options:['sine','deres','hendes','hans'],answer:1,
 why:'Если подлежащее во множественном числе, принадлежность выражается словом deres. Формы sin/sit/sine употребляются только при подлежащем в единственном числе 3-го лица, а hendes/hans указывали бы на другого человека.'},
{id:'g3-03',cat:'modal',type:'fix',
 sentence:'Børn bør ikke tilbringer mere end to timer foran skærmen om dagen.',errorIndex:3,fixes:['tilbringe'],
 why:'После модального глагола (bør) стоит инфинитив без at и без окончания -r: bør ikke tilbringe. Форма tilbringer — настоящее время.'},
{id:'g3-04',cat:'v2',type:'transform',
 prompt:'Vi mødes ved stationen klokken otte.',
 instruction:'Начни предложение с одного из обстоятельств: места (ved stationen) или времени (klokken otte).',
 answers:['Ved stationen mødes vi klokken otte.','Klokken otte mødes vi ved stationen.'],
 why:'После обстоятельства в начале предложения действует инверсия: глагол остаётся на втором месте, подлежащее идёт за ним (mødes vi, а не vi mødes).'},
{id:'g3-05',cat:'compare',type:'gap',
 stem:'Det var den ___ spændende film, jeg nogensinde har set.',
 options:['mere','flest','meget','mest'],answer:3,
 why:'Превосходная степень длинных прилагательных образуется с mest: den mest spændende. Mere — сравнительная степень, flest — превосходная от mange (о количестве), meget — «много, очень».'},
{id:'g3-06',cat:'passive',type:'transform',
 prompt:'Politiet fandt tasken i parken.',
 instruction:'Перепиши в пассиве. Деятеля (politiet) можно опустить или указать с af. Начни с: Tasken …',
 answers:['Tasken blev fundet i parken.','Tasken blev fundet af politiet i parken.','Tasken blev fundet i parken af politiet.'],
 why:'Пассив: blive + причастие (blev fundet). Форма fandtes здесь невозможна: она значила бы «существовала». Деятель вводится предлогом af и может отсутствовать.'},
{id:'g3-07',cat:'connect',type:'fix',
 sentence:'Hun spurgte mig, hvis jeg ville med i biografen.',errorIndex:3,fixes:['om'],
 why:'Hvis означает «если» (условие). Косвенный вопрос с вопросом «ли» вводится словом om: spurgte, om jeg ville med.'},
{id:'g3-08',cat:'bisaet',type:'order',
 tokens:['maden','Jeg','synes,','er','at','altid','for','dyr.'],
 answers:['Jeg synes, at maden altid er for dyr.'],
 why:'В придаточном предложении (at …) наречие altid стоит перед глаголом: at maden altid er for dyr. В главном предложении глагол шёл бы перед наречием: Maden er altid for dyr.'},
{id:'g3-09',cat:'tenses',type:'gap',
 stem:'Da jeg kom til stationen, ___ toget allerede kørt.',
 options:['var','er','havde','har'],answer:0,
 why:'Отъезд поезда произошёл раньше момента, когда я пришёл (kom), поэтому нужен pluskvamperfektum. Køre в значении «уехать» образует перфект с være: var kørt. Er и har — настоящее время, havde — не тот вспомогательный глагол.'},
{id:'g3-10',cat:'relative',type:'cloze',
 segments:['Anne er en kollega, ',{gap:1,options:['hvem','hvilket','der','hvis'],answer:2},' altid har tid til at hjælpe. Hun er også den slags menneske, ',{gap:2,options:['som','der','hvem','hvad'],answer:0},' alle kan lide. I går kom hun for sent, ',{gap:3,options:['hvad','hvilket','hvem','hvis'],answer:1},' irriterede chefen. Hun forklarede, at hun plejer at køre med en nabo, ',{gap:4,options:['der','som','hvilken','hvis'],answer:3},' bil ofte går i stykker. Derfor ved hun aldrig, ',{gap:5,options:['hvilket','hvilke','hvilken','hvad'],answer:2},' bus hun skal nå om morgenen.'],
 why:'Der — подлежащее придаточного, som — дополнение (den slags menneske, som alle kan lide). Hvilket относится ко всему предыдущему предложению, hvis означает «чей», а hvilken/hvilket/hvilke согласуются с существительным (hvilken bus).'}
]}
,{id:'gram-4',title:'Grammatik 4: By, natur og transport',level:'B2',minutes:15,items:[
{id:'g4-01',cat:'v2',type:'order',
 tokens:['fandt','Heldigvis','vi','hurtigt','en','ledig','parkeringsplads.'],
 answers:['Heldigvis fandt vi hurtigt en ledig parkeringsplads.','Vi fandt heldigvis hurtigt en ledig parkeringsplads.','Heldigvis fandt vi en ledig parkeringsplads hurtigt.','Vi fandt heldigvis en ledig parkeringsplads hurtigt.'],
 why:'Если предложение начинается с наречия (Heldigvis), глагол стоит на втором месте, а подлежащее — после него. Если начать с подлежащего, наречие следует за глаголом: Vi fandt heldigvis …'},
{id:'g4-02',cat:'agree',type:'gap',
 stem:'Den ___ bog, som jeg fik i fødselsdagsgave, er meget spændende.',
 options:['ny','nyt','nyen','nye'],answer:3,
 why:'После определённого артикля den прилагательное принимает форму на -e: den nye bog. Ny — неопределённая форма общего рода, nyt — среднего рода, а формы nyen не существует.'},
{id:'g4-03',cat:'reflex',type:'fix',
 sentence:'Mikkel skammede ham over, at han havde glemt aftalen.',errorIndex:2,fixes:['sig'],
 why:'Skamme sig over noget — возвратный глагол. Когда действие направлено на подлежащее (3-е лицо), нужно sig, а не ham: ham означало бы другого человека.'},
{id:'g4-04',cat:'cond',type:'transform',
 prompt:'Jeg kan ikke hjælpe dig, fordi jeg har travlt.',
 instruction:'Перепиши как нереальное условие. Начни с: Hvis jeg ikke … или с: Havde jeg ikke …',
 answers:['Hvis jeg ikke havde travlt, kunne jeg hjælpe dig.','Hvis jeg ikke havde travlt, ville jeg kunne hjælpe dig.','Havde jeg ikke travlt, kunne jeg hjælpe dig.','Havde jeg ikke travlt, ville jeg kunne hjælpe dig.'],
 why:'Нереальное условие: в условной части præteritum (havde), в главной — kunne или ville kunne. Условие можно выразить инверсией без hvis (Havde jeg ikke travlt, …). В придаточном с hvis слово ikke стоит перед глаголом.'},
{id:'g4-05',cat:'modal',type:'gap',
 stem:'Jeg har aldrig ___ køre bil, så jeg tager altid toget.',
 options:['kunnet','kunne','kan','kørt'],answer:0,
 why:'Перфект модального глагола образуется как har + kunnet, а затем следует инфинитив без at: har kunnet køre. Kunne — præteritum или инфинитив, kan — настоящее время, kørt не может стоять перед инфинитивом.'},
{id:'g4-06',cat:'bisaet',type:'order',
 tokens:['hvorfor','Jeg','ikke,','ved','han','altid','kommer','for','sent.'],
 answers:['Jeg ved ikke, hvorfor han altid kommer for sent.'],
 why:'В косвенном вопросе порядок слов как в придаточном: подлежащее, затем наречие, затем глагол — hvorfor han altid kommer, без инверсии.'},
{id:'g4-07',cat:'compare',type:'fix',
 sentence:'Hun har læst flest bøger end alle andre i klassen.',errorIndex:3,fixes:['flere'],
 why:'Для сравнения с end нужна сравнительная степень: flere bøger end alle andre. Flest — превосходная степень, она не сочетается с end.'},
{id:'g4-08',cat:'passive',type:'transform',
 prompt:'Man skal sende ansøgningen inden fredag.',
 instruction:'Перепиши в пассиве. Начни с: Ansøgningen …',
 answers:['Ansøgningen skal sendes inden fredag.','Ansøgningen skal blive sendt inden fredag.'],
 why:'После модального глагола пассив — это инфинитив пассива: sendes (форма на -s) или blive sendt. Объект ansøgningen становится подлежащим, man исчезает.'},
{id:'g4-09',cat:'tenses',type:'gap',
 stem:'Siden jeg flyttede hertil, ___ jeg kun set min familie to gange, og jeg savner dem stadig.',
 options:['havde','blev','har','er'],answer:2,
 why:'Период тянется до настоящего момента (jeg savner stadig), поэтому нужен perfektum: har set. Havde означало бы время до другого прошедшего момента, blev и er не подходят к причастию set.'},
{id:'g4-10',cat:'prep',type:'cloze',
 segments:['Kasper arbejder som mekaniker, men han drømmer ',{gap:1,options:['af','om','for','på'],answer:1},' at åbne sin egen cykelbutik. Han er bange ',{gap:2,options:['for','af','over','til'],answer:0},' at miste sit job, før butikken er klar. Hver lørdag venter han ',{gap:3,options:['for','til','ved','på'],answer:3},' en pakke med reservedele, og så mødes han ',{gap:4,options:['til','af','med','for'],answer:2},' sine venner i værkstedet. Om sommeren tager de ud ',{gap:5,options:['om','på','i','ved'],answer:1},' en lang cykeltur.'],
 why:'Это устойчивые сочетания, которые нужно учить целиком: drømme om, være bange for, vente på, mødes med, tage ud på en tur. Другие предлоги здесь не употребляются.'}
]}
,{id:'gram-5',title:'Grammatik 5: Uddannelse og samfund',level:'B2',minutes:15,items:[
{id:'g5-01',cat:'relative',type:'gap',
 stem:'Det er den lærer, ___ jeg har fået mest hjælp af.',
 options:['der','som','hvem','hvad'],answer:1,
 why:'Som — относительное слово для дополнения (jeg har fået hjælp af læreren), а der может быть только подлежащим. Hvem и hvad не вводят определительное придаточное при существительном.'},
{id:'g5-02',cat:'v2',type:'order',
 tokens:['har','Hvorfor','du','ikke','svaret','på','min','mail?'],
 answers:['Hvorfor har du ikke svaret på min mail?'],
 why:'В вопросе с вопросительным словом оно стоит первым, глагол — на втором месте, затем подлежащее, а ikke — после подлежащего: Hvorfor har du ikke svaret …?'},
{id:'g5-03',cat:'prep',type:'fix',
 sentence:'Mange unge er blevet meget afhængige på deres telefon.',errorIndex:6,fixes:['af'],
 why:'Устойчивое сочетание: afhængig af noget. Предлог på с этим прилагательным невозможен.'},
{id:'g5-04',cat:'connect',type:'transform',
 prompt:'Vi tog en taxa. Det regnede kraftigt.',
 instruction:'Объедини два предложения с помощью fordi. Начни с: Vi … или с: Fordi …',
 answers:['Vi tog en taxa, fordi det regnede kraftigt.','Fordi det regnede kraftigt, tog vi en taxa.'],
 why:'Fordi вводит придаточное причины, где подлежащее стоит перед глаголом (fordi det regnede). Если придаточное стоит первым, в главном предложении глагол идёт перед подлежащим: …, tog vi en taxa.'},
{id:'g5-05',cat:'reflex',type:'gap',
 stem:'Når man rejser alene, skal man passe godt på ___ selv.',
 options:['sig','ham','dem','sin'],answer:0,
 why:'Когда действие возвращается к подлежащему (man), используется возвратное sig: passe på sig selv. Ham и dem указывали бы на других людей, а sin selv не бывает.'},
{id:'g5-06',cat:'agree',type:'cloze',
 segments:['Min søster har fået ',{gap:1,options:['en','den','et','det'],answer:2},' nyt job på ',{gap:2,options:['et','den','det','en'],answer:3},' stor skole i Aarhus, og hun flytter derop allerede næste måned. Hun skal undervise de ',{gap:3,options:['nye','ny','nyt','nyes'],answer:0},' elever i dansk og historie. Skolen har en ',{gap:4,options:['lyse','lys','lyst','lysen'],answer:1},' gymnastiksal og mange moderne klasseværelser, og der er også en lille have bag bygningen. Lærerne er meget ',{gap:5,options:['glad','gladt','glade','gladde'],answer:2},' for de nye lokaler.'],
 why:'Артикль и прилагательное согласуются с родом и числом: job — средний род (et nyt job), skole — общий (en stor skole), после de прилагательное имеет окончание -e (de nye elever), en lys gymnastiksal, а сказуемое при подлежащем во множественном числе — glade.'},
{id:'g5-07',cat:'compare',type:'fix',
 sentence:'Det er det bedre tilbud, jeg nogensinde har fået.',errorIndex:3,fixes:['bedste'],
 why:'Когда речь о лучшем из всех («когда-либо»), нужна превосходная степень: det bedste tilbud. Bedre — сравнительная степень, она требует сравнения с чем-то (bedre end …).'},
{id:'g5-08',cat:'cond',type:'transform',
 prompt:'Desværre har jeg ikke mere tid.',
 instruction:'Перепиши как нереальное желание о настоящем. Начни с: Gid jeg … или с: Hvis jeg …',
 answers:['Gid jeg havde mere tid.','Gid jeg bare havde mere tid.','Hvis jeg havde mere tid.','Hvis jeg bare havde mere tid.'],
 why:'Нереальное желание о настоящем выражается конструкцией Gid jeg … или Hvis jeg (bare) … + præteritum (havde). Слово bare усиливает желание.'},
{id:'g5-09',cat:'modal',type:'gap',
 stem:'Jeg glemte ___ ringe til tandlægen, så nu må jeg vente en uge.',
 options:['for at','til at','kunne','at'],answer:3,
 why:'После glemme инфинитив вводится частицей at: glemte at ringe. For at и til at выражают цель, а модальный глагол kunne с glemte не сочетается.'},
{id:'g5-10',cat:'bisaet',type:'order',
 tokens:['du','Hvis','ikke','har','tid,','kan','jeg','gøre','det','i','stedet.'],
 answers:['Hvis du ikke har tid, kan jeg gøre det i stedet.'],
 why:'В придаточном (hvis …) отрицание ikke стоит перед глаголом: hvis du ikke har tid. Затем в главном предложении после придаточного идёт инверсия: kan jeg.'}
]}
,{id:'gram-6',title:'Grammatik 6: Sundhed og arbejdsliv',level:'B2',minutes:15,items:[
{id:'g6-01',cat:'connect',type:'gap',
 stem:'Vi tager ikke afsted, ___ vejret bliver bedre, for vi vil ikke køre i regnvejr.',
 options:['medmindre','selvom','fordi','efter'],answer:0,
 why:'Medmindre означает «если только не»: поездка отменяется, если погода не улучшится. Selvom — «хотя», fordi — «потому что», а как союз efter требует at (efter at).'},
{id:'g6-02',cat:'passive',type:'transform',
 prompt:'Direktionen har aflyst mødet.',
 instruction:'Перепиши в пассиве. Деятеля (direktionen) можно опустить или указать с af. Начни с: Mødet …',
 answers:['Mødet er blevet aflyst.','Mødet er aflyst.','Mødet er blevet aflyst af direktionen.','Mødet er aflyst af direktionen.'],
 why:'Перфект пассива образуется как er blevet + причастие (er blevet aflyst); часто используется и форма-состояние er aflyst. Деятель вводится предлогом af или опускается.'},
{id:'g6-03',cat:'tenses',type:'fix',
 sentence:'Jeg har allerede skrive til lægen, men han har ikke svaret.',errorIndex:3,fixes:['skrevet'],
 why:'После har в perfektum нужно причастие (supinum): har skrevet. Форма skrive — это инфинитив.'},
{id:'g6-04',cat:'reflex',type:'order',
 tokens:['glæder','Hun','sig','til','at','se','sine','børnebørn','igen.'],
 answers:['Hun glæder sig til at se sine børnebørn igen.'],
 why:'Glæde sig til — возвратный глагол, поэтому после него стоит sig. Притяжательное sine относится к подлежащему (Hun) и согласуется с существительным во множественном числе: sine børnebørn.'},
{id:'g6-05',cat:'agree',type:'gap',
 stem:'Hun har to ___, og begge går i børnehave.',
 options:['børnene','barn','børn','børnen'],answer:2,
 why:'После числительного нужна неопределённая форма множественного числа. У слова barn она неправильная: børn. Børnene — определённая форма, barn — единственное число, формы børnen не существует.'},
{id:'g6-06',cat:'cond',type:'transform',
 prompt:'Hun kom ikke til festen, fordi hun var syg.',
 instruction:'Перепиши как нереальное условие в прошлом. Начни с: Hvis hun … или с: Havde hun …',
 answers:['Hvis hun ikke havde været syg, ville hun være kommet til festen.','Hvis hun ikke havde været syg, var hun kommet til festen.','Havde hun ikke været syg, ville hun være kommet til festen.','Havde hun ikke været syg, var hun kommet til festen.'],
 why:'Нереальное условие в прошлом: в условной части havde + причастие (havde været), в главной — ville være kommet или просто var kommet. Условие можно выразить инверсией без hvis: Havde hun ikke været syg, …'},
{id:'g6-07',cat:'relative',type:'fix',
 sentence:'Min nabo, hvem hund larmede hele natten, er flyttet.',errorIndex:2,fixes:['hvis'],
 why:'Значение «чей» в относительном придаточном передаёт слово hvis: nabo, hvis hund … Hvem вопросительное слово и принадлежность не выражает.'},
{id:'g6-08',cat:'modal',type:'order',
 tokens:['gjort','ikke','Vi','uden','have','dig.','kunne','det'],
 answers:['Vi kunne ikke have gjort det uden dig.','Det kunne vi ikke have gjort uden dig.','Uden dig kunne vi ikke have gjort det.'],
 why:'После модального глагола kunne идёт инфинитив перфекта без at: kunne ikke have gjort. Дополнение det можно вынести на первое место — тогда подлежащее идёт после глагола: Det kunne vi …'},
{id:'g6-09',cat:'prep',type:'gap',
 stem:'Jeg er virkelig træt ___ at vente på svar.',
 options:['for','af','over','til'],answer:1,
 why:'Устойчивое сочетание: være træt af noget или af at gøre noget. Другие предлоги с этим прилагательным не употребляются.'},
{id:'g6-10',cat:'compare',type:'cloze',
 segments:['Mange tror, at man skal træne hårdt for at blive sund, men det er ikke rigtigt. Det er ',{gap:1,options:['godere','bedst','mere godt','bedre'],answer:3},' at bevæge sig lidt hver dag end at træne hårdt én gang om ugen. Lægen anbefaler også, at vi spiser ',{gap:2,options:['flere','mere','mest','mange'],answer:1},' frugt og mindre sukker. Desværre sover ',{gap:3,options:['meget','mere','mest','mange'],answer:3},' unge for lidt, selvom søvn er ',{gap:4,options:['lige så','mere','mest','meget'],answer:0},' vigtig som kost. Og husk: jo ',{gap:5,options:['flere','mest','mere','mange'],answer:2},' man øver sig, jo lettere bliver det.'],
 why:'Bedre — сравнительная степень от god (формы godere нет). Mere употребляется с неисчисляемыми (mere frugt), mange — со счётными во множественном числе (mange unge). Конструкция lige så … som выражает равенство, а jo mere …, jo lettere — «чем больше, тем легче».'}
]}
];
